246	function publish(p, slug, f, bins, rec, folder = p) {
247	  const ids = Object.keys(f.cases), bad = problems(f, ids);
248	  for (const id of ids) if (bins[id].length !== f.width * f.height) bad.push(`${id}.bin size`);
249	  if (bad.length) throw new Error(`${p}: ${bad.join("; ")}`);
250	  const dir = new URL(`${slug}/cfd/${folder}/`, STOPS);
251	  write(new URL("field.json", dir), JSON.stringify(f));
252	  for (const id of ids) write(new URL(`${id}.bin`, dir), bins[id]);
253	  write(new URL(`${p}.json`, RESULTS), JSON.stringify({ part: p, generated: `node tools/cfd/part.mjs ${p} export`, ...rec }, null, 1) + "\n");
