10	export function load(name, dir = OUT) {
11	  const m = JSON.parse(readFileSync(new URL(`${name}.json`, dir))), N = m.nx * m.ny * m.nz;
12	  const b = readFileSync(new URL(`${name}.bin`, dir)), solid = readFileSync(new URL(`${name}.solid`, dir));
13	  if (b.byteLength !== 16 * N) throw new Error(`${name}.bin: ${b.byteLength} bytes, want ${16 * N}`);
14	  if (solid.byteLength !== N) throw new Error(`${name}.solid: ${solid.byteLength} bytes, want ${N}`);
15	  const f = new Float32Array(b.buffer, b.byteOffset, 4 * N);
16	  return volume({ ...m, rho: f.subarray(0, N), ui: f.subarray(N, 2 * N), uj: f.subarray(2 * N, 3 * N), uk: f.subarray(3 * N), solid });
