19	// Adds the cell maths to a run's fields: at(i, j, k), centre(i, j, k) → [x, y, z] mm, cell(x, y, z) → [i, j, k] (nearest,
20	// clamped), and vel(x, y, z): the trilinear mean velocity in the vehicle frame (x forward, so the rearward lattice
21	// velocity is negated), in units of the inlet speed; null inside or next to a solid or outside the lattice. Mirrored
22	// runs (y0 = 0) read y < 0 through the mirror.
23	export function volume(r) {
24	  const { nx, ny, nz, h, x0, U } = r, y0 = r.y0 ?? 0, mirror = y0 === 0;
25	  const at = (i, j, k) => (k * ny + j) * nx + i;
26	  const centre = (i, j, k) => [x0 - (i + 0.5) * h, y0 + (j + 0.5) * h, (k + 0.5) * h];
27	  const clamp = (v, n) => Math.max(0, Math.min(n - 1, v));
28	  const cell = (x, y, z) => [clamp(Math.round((x0 - x) / h - 0.5), nx), ny === 1 ? 0 : clamp(Math.round(((mirror ? Math.abs(y) : y) - y0) / h - 0.5), ny), clamp(Math.round(z / h - 0.5), nz)];
29	  const vel = (x, y, z) => {
30	    const yy = mirror ? Math.abs(y) : y, fi = (x0 - x) / h - 0.5, fj = (yy - y0) / h - 0.5, fk = z / h - 0.5;
31	    if (fi < 0 || fi >= nx - 1 || fk < 0 || fk >= nz - 1) return null;
32	    if (ny > 1 && (fj >= ny - 1 || (!mirror && fj < 0))) return null;   // a single row (a 2-D run) is the same at every y
33	    const i0 = fi | 0, k0 = fk | 0, a = fi - i0, c = fk - k0, j0 = ny > 1 ? Math.max(0, Math.min(ny - 2, Math.floor(fj))) : 0, b = ny > 1 ? Math.max(0, Math.min(1, fj - j0)) : 0;
34	    let u = 0, v = 0, w = 0;
35	    for (let n = 0; n < 8; n++) {
36	      const di = n & 1, dj = (n >> 1) & 1, dk = n >> 2;
37	      if (dj && ny === 1) continue;
38	      const q = at(i0 + di, j0 + dj, k0 + dk);
39	      if (r.solid[q]) return null;
40	      const wt = (di ? a : 1 - a) * (dj ? b : 1 - b) * (dk ? c : 1 - c);
41	      u += wt * r.ui[q]; v += wt * r.uj[q]; w += wt * r.uk[q];
42	    }
43	    return [-u / U, (mirror && y < 0 ? -1 : 1) * v / U, w / U];
44	  };
45	  return { ...r, y0, N: nx * ny * nz, at, centre, cell, vel };
46	}
