49	// its direction in the side view: atan2(up, rearward) in degrees (+ = air rising as it leaves rearward).
50	export function probe(r, box) {
51	  let n = 0, ui = 0, uk = 0, uj = 0;
52	  for (let k = 0; k < r.nz; k++) for (let j = 0; j < r.ny; j++) for (let i = 0; i < r.nx; i++) {
53	    const [x, y, z] = r.centre(i, j, k);
54	    if (x < box.x[0] || x > box.x[1] || y < box.y[0] || y > box.y[1] || z < box.z[0] || z > box.z[1]) continue;
55	    const c = r.at(i, j, k); if (r.solid[c]) continue;
56	    n++; ui += r.ui[c]; uj += r.uj[c]; uk += r.uk[c];
57	  }
58	  ui /= n; uj /= n; uk /= n;
59	  return { n, rearward: ui / r.U, lateral: uj / r.U, up: uk / r.U, angle: Math.atan2(uk, ui) * 180 / Math.PI };
60	}
