62	// A path through the mean flow from a seed (mm), RK2 with step dt (mm per unit inlet speed), every `every`-th point kept,
63	// until it meets a solid, leaves the lattice or the box `stop` ({ x, y, z } ranges, any omitted). `plane` keeps one
64	// coordinate fixed ("y" for a side view, "z" for a plan view): the path then follows the velocity projected into it.
65	export function trace(r, seed, { dt = 10, n = 2000, every = 4, plane = null, stop = {} } = {}) {
66	  let [x, y, z] = seed;
67	  const pts = [[x, y, z]], fix = v => { if (plane === "y") v[1] = 0; if (plane === "z") v[2] = 0; return v; };
68	  const out = (x, y, z) => ["x", "y", "z"].some((ax, d) => stop[ax] && ([x, y, z][d] < stop[ax][0] || [x, y, z][d] > stop[ax][1]));
69	  for (let s = 0; s < n; s++) {
70	    const a = r.vel(x, y, z); if (!a) break; fix(a);
71	    const b = r.vel(x + a[0] * dt, y + a[1] * dt, z + a[2] * dt); if (!b) break; fix(b);
72	    x += (a[0] + b[0]) / 2 * dt; y += (a[1] + b[1]) / 2 * dt; z += (a[2] + b[2]) / 2 * dt;
73	    if (out(x, y, z)) break;
74	    if (s % every === every - 1) pts.push([x, y, z]);
75	  }
76	  return pts.map(p => p.map(v => Math.round(v)));
77	}

