  if(q[0]<=-600){let f=(-600-p[0])/(q[0]-p[0]);p=p.map((v,i)=>v+(q[i]-v)*f);break;}p=q;
 }
 console.log(plane,method,dt,p.map(x=>x.toFixed(1)),dymin,n);
